import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/outlierr/2021_energy.csv')
adj_df = pd.read_csv('ADJACENCY_PATH')

# Prepare adjacency dictionary
adjacency = {}
for borough in df['borough'].unique():
    neighbors = adj_df[adj_df['borough'] == borough]['neighbor'].tolist()
    adjacency[borough] = neighbors

# Initialize variables
energy_values = df.set_index('borough')['Energy_value'].to_dict()
boroughs = list(energy_values.keys())
n = len(boroughs)

# Iterative-R method implementation
def iterative_r_outlier_detection(energy_values, adjacency, max_iter=10, threshold=2.5):
    residuals = {}
    standardized_residuals = {}

    # Initial pass
    for borough in boroughs:
        neighbors = adjacency.get(borough, [])
        neighbor_values = [energy_values[n] for n in neighbors if n in energy_values]
        if neighbor_values:
            neighbor_mean = np.mean(neighbor_values)
            residuals[borough] = energy_values[borough] - neighbor_mean
        else:
            residuals[borough] = 0

    # Calculate global mean and std of residuals
    global_mean = np.mean(list(residuals.values()))
    global_std = np.std(list(residuals.values()))

    # Standardize residuals
    for borough in boroughs:
        if global_std > 0:
            standardized_residuals[borough] = (residuals[borough] - global_mean) / global_std
        else:
            standardized_residuals[borough] = 0

    # Iterative refinement
    for _ in range(max_iter):
        # Identify potential outliers (absolute standardized residual > threshold)
        potential_outliers = [b for b in boroughs if abs(standardized_residuals[b]) > threshold]

        if not potential_outliers:
            break

        # Recompute residuals excluding potential outliers
        clean_energy = {b: energy_values[b] for b in boroughs if b not in potential_outliers}
        clean_adjacency = {b: [n for n in neighbors if n not in potential_outliers] 
                          for b, neighbors in adjacency.items()}

        new_residuals = {}
        for borough in boroughs:
            neighbors = clean_adjacency.get(borough, [])
            neighbor_values = [clean_energy[n] for n in neighbors if n in clean_energy]
            if neighbor_values:
                neighbor_mean = np.mean(neighbor_values)
                new_residuals[borough] = energy_values[borough] - neighbor_mean
            else:
                new_residuals[borough] = 0

        # Update global stats
        global_mean = np.mean(list(new_residuals.values()))
        global_std = np.std(list(new_residuals.values()))

        # Update standardized residuals
        for borough in boroughs:
            if global_std > 0:
                standardized_residuals[borough] = (new_residuals[borough] - global_mean) / global_std
            else:
                standardized_residuals[borough] = 0

    return standardized_residuals

# Run detection
standardized_residuals = iterative_r_outlier_detection(energy_values, adjacency)

# Get Barnet's result
barnet_z = standardized_residuals['Barnet']

# Determine final answer
if abs(barnet_z) > 2.5:
    if barnet_z > 0:
        print(f"FINAL ANSWER: OUTLIER - HIGH (z = {barnet_z})")
    else:
        print(f"FINAL ANSWER: OUTLIER - LOW (z = {barnet_z})")
else:
    print(f"FINAL ANSWER: NOT AN OUTLIER (z = {barnet_z})")
